export function LogoMark({ className, arrowClassName }: { className?: string; arrowClassName?: string }) {
  return (
    <svg viewBox="481.9 207.9 583.6 267.6" className={className} aria-hidden>
      <g fillRule="evenodd">
        <path fill="currentColor" d={MARK_WHITE} />
        <path fill={BRAND_PURPLE} d={MARK_UP} className={arrowClassName} />
      </g>
    </svg>
  );
}

// Mark and wordmark side by side, for headers.
export function Logo({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 1825 231" className={cn("block h-6 w-auto", className)} role="img" aria-label="OpenSpot">
      <g fillRule="evenodd" transform="translate(-459.1 -203.4) scale(0.9333)">
        <path fill="currentColor" d={MARK_WHITE} />
        <path fill={BRAND_PURPLE} d={MARK_UP} className="logo-arrow" />
      </g>
      <g fillRule="evenodd" transform="translate(426.6 -523.9)">
        <path fill="currentColor" d={WORD_WHITE} />
        <path fill={BRAND_PURPLE} d={WORD_UP} />
      </g>
    </svg>
  );
}
